function earliestTwoRides(landStart: number[], landDuration: number[], waterStart: number[], waterDuration: number[]): number {
  let best = Infinity;
  for (let i = 0; i < landStart.length; i++) {
    for (let j = 0; j < waterStart.length; j++) {
      const landEnd = landStart[i] + landDuration[i];
      const waterEnd = waterStart[j] + waterDuration[j];
      best = Math.min(best,
        Math.max(landEnd, waterStart[j]) + waterDuration[j],
        Math.max(waterEnd, landStart[i]) + landDuration[i]);
    }
  }
  return best;
}

