function earliestTwoRides(landStart: number[], landDuration: number[], waterStart: number[], waterDuration: number[]): number {
  const finish = (aStart: number[], aDur: number[], bStart: number[], bDur: number[]): number => {
    let firstEnd = Infinity;
    for (let i = 0; i < aStart.length; i++) firstEnd = Math.min(firstEnd, aStart[i] + aDur[i]);
    let best = Infinity;
    for (let j = 0; j < bStart.length; j++) best = Math.min(best, Math.max(firstEnd, bStart[j]) + bDur[j]);
    return best;
  };
  return Math.min(
    finish(landStart, landDuration, waterStart, waterDuration),
    finish(waterStart, waterDuration, landStart, landDuration)
  );
}

